use super::*;
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:262144,maximum_depth:4096}}
fn observe<T>(run:impl FnOnce()->(T,RetainedCloneProgress))->T{let((value,p),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);assert!(p.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));value}
fn close<T:semio_framework_value::retirement::RetireOwned>(value:T){let mut value=Some(value);let mut retirement=RetainedCloneClose::default();for index in 0..100000{if value.is_none()&&retirement.is_empty(){return}let d=retirement.next_owner_demands::<T>(value.is_some(),&None,4096).unwrap();let g=RetainedCloneGrant{maximum_copy_bytes:grant().maximum_copy_bytes.max(d.copy_bytes),maximum_capacity_bytes:grant().maximum_capacity_bytes.max(d.capacity_bytes),..grant()};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||retirement.begin_granted(&mut value,g).unwrap().unwrap_or_else(||retirement.step_granted(g).unwrap()));assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(index<99999)}panic!("original history envelope fixture retained its payload")}
#[test]
fn original_history_envelope_moves_actual_pages_and_headers_and_closes_each_partial_copy(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){for cut in [0,1,2,4,8,16,usize::MAX]{let document=case["document"].as_str().unwrap();let actor=ActorId(case["actor"].as_str().unwrap().into());let observed=case["observed"].as_str();let mut owner=OriginalHistoryEnvelopeHeader::default();for index in 0..1000{if index==cut{break}if owner.ready(){break}let d=owner.demands(document,&actor,observed,4096).unwrap();for axis in 0..5{let amount=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,3=>d.release_bytes,_=>d.depth};if amount==0{continue}let mut g=grant();match axis{0=>g.maximum_items=0,1=>g.maximum_copy_bytes=amount-1,2=>g.maximum_capacity_bytes=amount-1,3=>g.maximum_release_bytes=amount-1,_=>g.maximum_depth=amount-1}observe(||{let p=owner.advance(document,&actor,observed,g).unwrap();assert_eq!(p,Default::default());((),p)});}observe(||{let p=owner.advance(document,&actor,observed,grant()).unwrap();((),p)});let foreign=document.to_owned();let(error,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&foreign,&actor,observed,grant()).unwrap_err());assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(index<999)}if cut==usize::MAX{assert!(owner.ready());let mut dependencies:Vec<MutationId>=case["dependencies"].as_array().unwrap().iter().map(|value|MutationId(value.as_str().unwrap().to_owned())).collect();let mut target:Vec<String>=case["target"].as_array().unwrap().iter().map(|value|value.as_str().unwrap().to_owned()).collect();let dep_pointer=dependencies.as_ptr();let target_pointer=target.as_ptr();let payload=CausalPayload::try_from_slice(b"original history payload").unwrap();let identity=String::from("transition-original");let identity_pointer=identity.as_ptr();let mut payload=Some((payload,MutationId(identity)));let timestamp=HybridLogicalTimestamp::new(71,19);let envelope=observe(||{let(value,p)=owner.take(&mut payload,&mut dependencies,&mut target,timestamp,grant()).unwrap().unwrap();(value,p)});assert_eq!(envelope.dependencies.as_ptr(),dep_pointer);assert_eq!(envelope.target.as_ptr(),target_pointer);assert_eq!(envelope.mutation_id.0.as_ptr(),identity_pointer);assert!(payload.is_none()&&dependencies.capacity()==0&&target.capacity()==0);let expected=&case["expected"];assert_eq!(envelope.document_id.0,expected["document"].as_str().unwrap());assert_eq!(envelope.actor.0.as_str(),expected["actor"].as_str().unwrap());assert_eq!(envelope.observed.as_ref().map(|id|id.0.as_str()),expected["observed"].as_str());assert_eq!(envelope.diff.schema.0,expected["schema"].as_str().unwrap());assert_eq!(envelope.inverse.schema,envelope.diff.schema);assert_eq!(envelope.inverse.payload.len(),expected["inverseBytes"].as_u64().unwrap()as usize);assert!(envelope.transaction.is_none()&&envelope.verb.is_none()&&envelope.line.is_none());close(envelope);}for index in 0..100000{if owner.terminal_is_empty(){break}observe(||{let step=owner.close_step(grant()).unwrap();((),step.progress())});assert!(index<99999)}assert!(owner.terminal_is_empty());close(actor);}}}
